#include "stdafx.h"#include "ReadParamsFromEMF.h"#include "SignalTags.h"#include "Variable.h"#include <macros/AutoCloser.h>#include <macros/StrHelps.h>void KReadParamsFromEMF::ReadAllSignalTagsVariables( LPCTSTR lpszPathName ){  FILE *pFileI = NULL;  errno_t res = fopen_s( &pFileI, lpszPathName, "rt" );  if( res )    return;  KAutoCloser<FILE*> fI( pFileI, fclose );  char tStr[1024] = {0};  int nLine = 0;  int nCol = 0;  while( fgets( tStr, _countof(tStr)-1, pFileI ) )  {    char szCol[24][64] = {};    ++nLine;    const int C = SplitString( tStr, szCol, ',', false );    ASSD( C < _countof(szCol) );    if( 1==nLine )      continue;    if( 0==szCol[5][0] )      continue;    if( !strcmp(szCol[5], "Signal Tag") )    {      ISignalTagPtr I;      if( !strcmp(szCol[11], "Digital") )      {        KDigitalSignalTag *p = new KDigitalSignalTag;        I = p;        tNamedSignalTags::_Pairib res = m_SignalTags.insert( tNamedSignalTags::value_type( szCol[3], I ) );        if( !res.second )          continue;        I->SetDecPics( atoi(szCol[10]) );        p->SetOnLabel( szCol[12] );        p->SetOffLabel( szCol[13] );      }      else if( !strcmp(szCol[11], "Analog") )      {        KAnalogSignalTag *p = new KAnalogSignalTag;        I = p;        tNamedSignalTags::_Pairib res = m_SignalTags.insert( tNamedSignalTags::value_type( szCol[3], I ) );        if( !res.second )          continue;      }      else      {        ASSD(0);        continue;      }      I->SetDescription( szCol[4] );      I->SetNumber( atoi(szCol[6]) );      I->SetDataType( szCol[7] );      I->SetAccess( szCol[8] );      I->SetUnits( szCol[9] );      I->SetInitialSourceValue( szCol[14] );    }    else if( !strcmp(szCol[5], "Variable") )    {      ISignalTagPtr I;      if( !strcmp(szCol[11], "Digital") )      {        KDigitalVariable *p = new KDigitalVariable;        I = p;        tNamedVariables::_Pairib res = m_Variables.insert( tNamedVariables::value_type( szCol[3], I ) );        if( !res.second )          continue;        I->SetDecPics( atoi(szCol[10]) );        p->SetOnLabel( szCol[12] );        p->SetOffLabel( szCol[13] );      }      else if( !strcmp(szCol[11], "Analog") )      {        KAnalogVariable *p = new KAnalogVariable;        I = p;        tNamedVariables::_Pairib res = m_Variables.insert( tNamedVariables::value_type( szCol[3], I ) );        if( !res.second )          continue;      }      else      {        ASSD(0);        continue;      }      tNumberedVarCont::_Pairib npair = m_numberedVars.insert( tNumberedVarCont::value_type( atoi(szCol[6]), I ) );      ASSD( npair.second );      I->SetDescription( szCol[4] );      I->SetNumber( atoi(szCol[6]) );      I->SetDataType( szCol[7] );      I->SetAccess( szCol[8] );      I->SetUnits( szCol[9] );      I->SetInitialSourceValue( szCol[14] );    }  }}